def count_nums(arr):
    """
    Write a function count_nums which takes an array of integers and returns the number of elements which has a sum of digits > 0
    If a number is negative, then its first signed digit will be negative
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def digit_sum(n):
        """Helper function to calculate the sum of digits of a number."""
        if n < 0:
            return sum(int(digit) for digit in str(abs(n)))

        else:
            return sum(int(digit) for digit in str(n))

    count = 0
    for num in arr:
        if digit_sum(num) > 0:
            count += 1

    return count

# Test cases
print(count_nums([]))  # Output: 0
print(count_nums([-1, 11, -11]))  # Output: 1
print(count_nums([1, 1, 2]))  # Output: 3
